changeSet.sql:
DROP TRIGGER IF EXISTS trg_audit_logs_worm_prevent_delete_update;
DELETE FROM audit_logs;
CREATE TRIGGER IF NOT EXISTS trg_audit_logs_worm_prevent_delete_update
BEFORE DELETE, UPDATE ON audit_logs
FOR EACH ROW
CALL "dev.legatus.server.security.WormAuditLogTrigger";
UPDATE tasks SET status = 'COMPLETED' WHERE status = 'EXECUTING';
